const StdTab = class {
    constructor(hostRef) {
        index.registerInstance(this, hostRef);
        this.itemSelected = index.createEvent(this, "itemSelected", 7);
        this.type = '';
        this.bgStyle = '';
        this.activeStyle = '';
        this.internalItems = [];
    }
    componentWillLoad() {
        this.parseOptions();
    }
    parseOptions() {
        let finalItems = [];
        if (!this.items)
            return;
        if (typeof this.items === 'string') {
            finalItems = JSON.parse(this.items);
        }
        else {
            finalItems = this.items;
        }
        this.internalItems = finalItems;
    }
    render() {
        const typeClassesTab = {
            primary: 'css-tab',
            secondary: 'css-tab--simple'
        }[this.type];
        const tabClasses = [typeClassesTab].join(' ').trim().replace(/\s+/g, ' ');
        // Header //
        const typeClasses = {
            primary: `inline-flex items-center gap-4 p-1 rounded-xl ${this.bgStyle || 'bg-alternative-light'}`,
            secondary: 'flex items-center gap-4 border-b border-alternative-medium'
        }[this.type];
        const tabHeaderClasses = [typeClasses].join(' ').trim().replace(/\s+/g, ' ');
        const buttonTypeClasses = {
            primary: ' px-8',
            secondary: 'px-2'
        }[this.type];
        const buttonClasses = ['css-tab-button  h-auto py-2 lg:py-3 text-base text-dark', buttonTypeClasses].join(' ').trim().replace(/\s+/g, ' ');
        const onChangeActive = (key) => {
            if (this.tabKey === key)
                return;
            this.tabKey = key;
            this.itemSelected.emit({ selectedKey: key });
        };
        return (index.h("div", { class: tabClasses }, index.h("ul", { class: tabHeaderClasses }, this.internalItems.map(item => (index.h("li", null, index.h("button", { onClick: () => onChangeActive(String(item.key)), class: `${buttonClasses} ${String(this.tabKey) === String(item.key)
                ? `is-active ${this.activeStyle || ''}`
                : ''}`, disabled: item.disabled }, item.label))))), index.h("div", { class: "pt-4" }, index.h("slot", null))));
    }
    static get watchers() { return {
        "items": ["parseOptions"]
    }; }
};
StdTab.style = stdTabCss;

